Here is the root cause:
The bug was caused by the incorrect handling of the `out_len` variable in the `ubifs_jnl_write_data` function, which was not being set properly for unencrypted data writes. This led to inconsistencies in the data length being written to the journal, resulting in errors during the journal loading process on reboot.

Here is the patch:
  */
 int ubifs_jnl_write_data(struct ubifs_info *c, const struct inode *inode,
 			 const union ubifs_key *key, const void *buf, int len)
 {
 	struct ubifs_data_node *data;
 	int err, lnum, offs, compr_type, out_len, compr_len;
 	int dlen = COMPRESSED_DATA_NODE_BUF_SZ, allocated = 1;
 	struct ubifs_inode *ui = ubifs_inode(inode);
 	bool encrypted = ubifs_crypt_is_encrypted(inode);

 	dbg_jnlk(key, "ino %lu, blk %u, len %d, key ",
 		(unsigned long)key_inum(c, key), key_block(c, key), len);
 	ubifs_assert(len <= UBIFS_BLOCK_SIZE);

 	if (encrypted)
 		dlen += UBIFS_CIPHER_BLOCK_SIZE;

 	data = kmalloc(dlen, GFP_NOFS | __GFP_NOWARN);
 	if (!data) {
 		/*
 		 * Fall-back to the write reserve buffer. Note, we might be
 		 * currently on the memory reclaim path, when the kernel is
 		 * trying to free some memory by writing out dirty pages. The
 		 * write reserve buffer helps us to guarantee that we are
 		 * always able to write the data.
 		 */
 		allocated = 0;
 		mutex_lock(&c->write_reserve_mutex);
 		data = c->write_reserve_buf;
 	}

 	data->ch.node_type = UBIFS_DATA_NODE;
 	key_write(c, key, &data->key);
 	data->size = cpu_to_le32(len);

 	if (!(ui->flags & UBIFS_COMPR_FL))
 		/* Compression is disabled for this inode */
 		compr_type = UBIFS_COMPR_NONE;
 	else
 		compr_type = ui->compr_type;

 	out_len = compr_len = dlen - UBIFS_DATA_NODE_SZ;
 	ubifs_compress(c, buf, len, &data->data, &compr_len, &compr_type);
 	ubifs_assert(compr_len <= UBIFS_BLOCK_SIZE);

 	if (encrypted) {
 		err = ubifs_encrypt(inode, data, compr_len, &out_len, key_block(c, key));
 		if (err)
 			goto out_free;

 	} else {
 		data->compr_size = 0;
+		out_len = compr_len;
 	}

 	dlen = UBIFS_DATA_NODE_SZ + out_len;
 	data->compr_type = cpu_to_le16(compr_type);

 	/* Make reservation before allocating sequence numbers */
 	err = make_reservation(c, DATAHD, dlen);
 	if (err)
 		goto out_free;

 	err = write_node(c, DATAHD, data, dlen, &lnum, &offs);
 	if (err)
 		goto out_release;
 	ubifs_wbuf_add_ino_nolock(&c->jheads[DATAHD].wbuf, key_inum(c, key));
 	release_head(c, DATAHD);

 	err = ubifs_tnc_add(c, key, lnum, offs, dlen);
 	if (err)
 		goto out_ro;

 	finish_reservation(c);
 	if (!allocated)
 		mutex_unlock(&c->write_reserve_mutex);
 	else
 		kfree(data);
 	return 0;

 out_release:
 	release_head(c, DATAHD);
 out_ro:
 	ubifs_ro_mode(c, err);
 	finish_reservation(c);
 out_free:
 	if (!allocated)
 		mutex_unlock(&c->write_reserve_mutex);
 	else
 		kfree(data);
 	return err;
 }



